def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    fg = next(v for v in counts if v != bg)
    for r in range(h - 1):
        row, nxt = grid[r], grid[r + 1]
        positions = [c for c, v in enumerate(row) if v == fg]
        if not positions:
            continue
        a, b = min(positions), max(positions)
        if positions != list(range(a, b + 1)) or any(v != bg for v in row[:a] + row[b + 1:]):
            continue
        lead = 0
        while lead < w and nxt[lead] == fg:
            lead += 1
        if lead and (b - a + 1 + lead) < w and all(v == bg for v in nxt[lead:]):
            for c in range(b + 1, w):
                out[r][c] = 1
    return out
